import{_ as e,C as t,c as i,o,a0 as a,b as n,w as r,a as l,G as s,a1 as u}from"./chunks/framework.DKRgXLPU.js";const d=JSON.parse('{"title":"Training Camp: Weekend Mental Game Intensive","description":"","frontmatter":{},"headers":[],"relativePath":"en/training-camp.md","filePath":"en/training-camp.md"}');const c=e({name:"en/training-camp.md"},[["render",function(e,d,c,p,h,g){const m=t("Mermaid");return o(),i("div",null,[d[2]||(d[2]=a('<h1 id="training-camp-weekend-mental-game-intensive" tabindex="-1">Training Camp: Weekend Mental Game Intensive <a class="header-anchor" href="#training-camp-weekend-mental-game-intensive" aria-label="Permalink to &quot;Training Camp: Weekend Mental Game Intensive&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>A comprehensive weekend training camp (Friday-Sunday) for 10-20 players that combines mental game theory, on-piste practice, and competitive application. This intensive format creates transformational learning through integration of all three elements.</p><div class="tip custom-block"><p class="custom-block-title">Two Sections in This Guide</p><ul><li><strong><a href="#for-participants">For Participants</a></strong> - What players will experience during the weekend</li><li><strong><a href="#for-organizers">For Organizers</a></strong> - How to plan and run the training camp</li></ul></div><div class="tip custom-block"><p class="custom-block-title">The Training Camp Philosophy</p><p><strong>Theory without practice is just information. Practice without theory is just repetition. Competition without reflection is just playing.</strong> This weekend integrates all three for transformational learning.</p></div><h2 id="quick-access" tabindex="-1">Quick Access <a class="header-anchor" href="#quick-access" aria-label="Permalink to &quot;Quick Access&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Section</th><th>Purpose</th><th>Access</th></tr></thead><tbody><tr><td><strong>For Participants</strong></td><td>Weekend schedule and what to bring</td><td><a href="#for-participants">View Section</a></td></tr><tr><td><strong>For Organizers</strong></td><td>Complete planning and facilitation guide</td><td><a href="#for-organizers">View Section</a></td></tr><tr><td><strong>Daily Schedules</strong></td><td>Detailed timing and activities</td><td><a href="#friday-evening-mental-game-foundation-3-4-hours">Friday</a> • <a href="#saturday-practice-application-full-day">Saturday</a> • <a href="#sunday-competition-integration-full-day">Sunday</a></td></tr><tr><td><strong>Related Guides</strong></td><td>Other training formats</td><td><a href="/en/mental-journey/">Mental Journey</a> • <a href="/en/workshop">Workshop</a></td></tr></tbody></table><hr><h2 id="for-participants" tabindex="-1">For Participants <a class="header-anchor" href="#for-participants" aria-label="Permalink to &quot;For Participants&quot;">​</a></h2><h3 id="what-to-expect" tabindex="-1">What to Expect <a class="header-anchor" href="#what-to-expect" aria-label="Permalink to &quot;What to Expect&quot;">​</a></h3><p>This is an intensive weekend that will challenge you mentally, physically, and emotionally. You&#39;ll learn mental game concepts, practice them on the piste, and apply them in competition - all while building deep connections with fellow players.</p><p><strong>Weekend Structure:</strong></p>',12)),(o(),n(u,null,{default:r(()=>[s(m,{id:"mermaid-105",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BWeekend%20Camp%5D%20--%3E%20B%5BFriday%3A%20Theory%5D%0A%20%20%20%20B%20--%3E%20C%5BSaturday%3A%20Practice%5D%0A%20%20%20%20C%20--%3E%20D%5BSunday%3A%20Competition%5D%0A%20%20%20%20D%20--%3E%20E%5BIntegration%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20B%20fill%3A%23fff4e1%0A%20%20%20%20style%20C%20fill%3A%23e3f2fd%0A%20%20%20%20style%20D%20fill%3A%23ffe4e1%0A%20%20%20%20style%20E%20fill%3A%23f3e5f5%0A"})]),fallback:r(()=>[...d[0]||(d[0]=[l(" Loading... ",-1)])]),_:1})),d[3]||(d[3]=a('<h3 id="daily-breakdown" tabindex="-1">Daily Breakdown <a class="header-anchor" href="#daily-breakdown" aria-label="Permalink to &quot;Daily Breakdown&quot;">​</a></h3><h4 id="friday-evening-mental-game-foundation-3-4-hours" tabindex="-1">Friday Evening: Mental Game Foundation (3-4 hours) <a class="header-anchor" href="#friday-evening-mental-game-foundation-3-4-hours" aria-label="Permalink to &quot;Friday Evening: Mental Game Foundation (3-4 hours)&quot;">​</a></h4><p><strong>What:</strong> Theory session on mental game concepts <strong>Where:</strong> Indoor meeting room <strong>Format:</strong> Circle discussion and exercises</p><p><strong>You&#39;ll Learn:</strong></p><ul><li>The Zone and flow states</li><li>Inner Critic vs Inner Coach</li><li>Pressure response patterns</li><li>Pre-shot routine fundamentals</li></ul><p><strong>Activities:</strong></p><ul><li>Check-in and ground rules</li><li>The Iceberg of Pétanque</li><li>User Manual creation</li><li>Fear in a Hat exercise</li></ul><h4 id="saturday-practice-application-full-day" tabindex="-1">Saturday: Practice &amp; Application (Full Day) <a class="header-anchor" href="#saturday-practice-application-full-day" aria-label="Permalink to &quot;Saturday: Practice &amp; Application (Full Day)&quot;">​</a></h4><p><strong>Morning (3 hours):</strong> Structured practice with mental focus <strong>Afternoon (3 hours):</strong> Pressure simulation drills <strong>Evening (2 hours):</strong> Reflection and integration</p><p><strong>You&#39;ll Practice:</strong></p><ul><li>Pre-shot routines in real throws</li><li>Reset techniques after mistakes</li><li>Focus anchors under pressure</li><li>Team communication protocols</li></ul><p><strong>Format:</strong></p><ul><li>Small group drills (3-4 players)</li><li>Video analysis of mental patterns</li><li>Pressure scenarios</li><li>Evening debrief session</li></ul><h4 id="sunday-competition-integration-full-day" tabindex="-1">Sunday: Competition &amp; Integration (Full Day) <a class="header-anchor" href="#sunday-competition-integration-full-day" aria-label="Permalink to &quot;Sunday: Competition &amp; Integration (Full Day)&quot;">​</a></h4><p><strong>Morning (3 hours):</strong> Tournament play <strong>Afternoon (2 hours):</strong> Final rounds <strong>Evening (1 hour):</strong> Closing reflection</p><p><strong>You&#39;ll Apply:</strong></p><ul><li>All mental tools in competition</li><li>Team protocols under pressure</li><li>Mistake recovery in real time</li><li>Post-game reflection process</li></ul><h3 id="what-to-bring" tabindex="-1">What to Bring <a class="header-anchor" href="#what-to-bring" aria-label="Permalink to &quot;What to Bring&quot;">​</a></h3><p><strong>Required:</strong></p><ul><li>Your boules and equipment</li><li>Comfortable clothing for all weather</li><li>Notebook and pen</li><li>Open mind and willingness to share</li><li>Water bottle</li></ul><p><strong>Optional:</strong></p><ul><li>Training diary</li><li>Questions about specific mental challenges</li><li>Examples of pressure situations you face</li></ul><p><strong>Not Needed:</strong></p><ul><li>Technical coaching requests (this is mental game focused)</li><li>Ego or need to prove yourself</li><li>Judgment of others</li></ul><h3 id="ground-rules-for-the-weekend" tabindex="-1">Ground Rules for the Weekend <a class="header-anchor" href="#ground-rules-for-the-weekend" aria-label="Permalink to &quot;Ground Rules for the Weekend&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">The Container</p><p>All participants agree to:</p><ol><li><strong>Confidentiality</strong> - What&#39;s shared stays here</li><li><strong>Respect</strong> - Honor others&#39; vulnerability</li><li><strong>Participation</strong> - Engage fully in all activities</li><li><strong>Growth Mindset</strong> - Embrace discomfort as learning</li><li><strong>Support</strong> - Help teammates apply concepts</li></ol></div><h3 id="what-you-ll-leave-with" tabindex="-1">What You&#39;ll Leave With <a class="header-anchor" href="#what-you-ll-leave-with" aria-label="Permalink to &quot;What You&#39;ll Leave With&quot;">​</a></h3><p><strong>Knowledge:</strong></p><ul><li>Deep understanding of your mental patterns</li><li>Practical tools for pressure management</li><li>Team protocols for competition</li><li>Personalized pre-shot routine</li></ul><p><strong>Skills:</strong></p><ul><li>Ability to access flow states</li><li>Mistake recovery techniques</li><li>Inner Coach reframing</li><li>Focus anchors</li></ul><p><strong>Connection:</strong></p><ul><li>Deeper bonds with teammates</li><li>Shared language for mental game</li><li>Support network for continued growth</li></ul><p><strong>Materials:</strong></p><ul><li>Completed worksheets and exercises</li><li>Video analysis of your mental patterns</li><li>Action plan for next 30 days</li><li>Access to all education modules</li></ul><h3 id="typical-schedule" tabindex="-1">Typical Schedule <a class="header-anchor" href="#typical-schedule" aria-label="Permalink to &quot;Typical Schedule&quot;">​</a></h3><p><strong>Friday:</strong></p><ul><li>18:00 - Arrival and check-in</li><li>19:00 - Dinner</li><li>20:00 - Opening session (theory)</li><li>23:00 - Free time / rest</li></ul><p><strong>Saturday:</strong></p><ul><li>08:00 - Breakfast</li><li>09:00 - Morning practice session</li><li>12:00 - Lunch</li><li>13:30 - Afternoon practice session</li><li>17:00 - Break</li><li>18:00 - Dinner</li><li>19:30 - Evening reflection session</li><li>21:00 - Free time / rest</li></ul><p><strong>Sunday:</strong></p><ul><li>08:00 - Breakfast</li><li>09:00 - Tournament begins</li><li>12:00 - Lunch</li><li>13:00 - Final rounds</li><li>15:00 - Awards and recognition</li><li>16:00 - Closing circle</li><li>17:00 - Departure</li></ul><hr><h2 id="for-organizers" tabindex="-1">For Organizers <a class="header-anchor" href="#for-organizers" aria-label="Permalink to &quot;For Organizers&quot;">​</a></h2><h3 id="planning-overview" tabindex="-1">Planning Overview <a class="header-anchor" href="#planning-overview" aria-label="Permalink to &quot;Planning Overview&quot;">​</a></h3><p>This section provides everything you need to organize and run a successful weekend training camp for 10-20 players.</p><h3 id="pre-camp-planning-6-8-weeks-before" tabindex="-1">Pre-Camp Planning (6-8 Weeks Before) <a class="header-anchor" href="#pre-camp-planning-6-8-weeks-before" aria-label="Permalink to &quot;Pre-Camp Planning (6-8 Weeks Before)&quot;">​</a></h3><h3 id="group-size-structure" tabindex="-1">Group Size &amp; Structure <a class="header-anchor" href="#group-size-structure" aria-label="Permalink to &quot;Group Size &amp; Structure&quot;">​</a></h3><p><strong>Optimal:</strong> 10-20 players</p><ul><li><strong>Small camp (10-12):</strong> More intimate, deeper sharing</li><li><strong>Large camp (16-20):</strong> More diverse perspectives, requires sub-groups</li></ul><p><strong>Team Structure:</strong></p><ul><li>Divide into teams of 3-4 for practice and competition</li><li>Mix skill levels and playing styles</li><li>Rotate teams throughout weekend</li></ul><h3 id="staffing-requirements" tabindex="-1">Staffing Requirements <a class="header-anchor" href="#staffing-requirements" aria-label="Permalink to &quot;Staffing Requirements&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Role</th><th>Responsibilities</th><th>Quantity</th></tr></thead><tbody><tr><td><strong>Mental Performance Coordinator</strong></td><td>Facilitate theory sessions, group dynamics</td><td>1</td></tr><tr><td><strong>Technical Coach</strong></td><td>Oversee practice, provide feedback</td><td>1-2</td></tr><tr><td><strong>Competition Director</strong></td><td>Run tournament, manage logistics</td><td>1</td></tr><tr><td><strong>Support Staff</strong></td><td>Meals, setup, admin</td><td>1-2</td></tr></tbody></table><h3 id="location-requirements" tabindex="-1">Location Requirements <a class="header-anchor" href="#location-requirements" aria-label="Permalink to &quot;Location Requirements&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">Facility Needs</p><p><strong>Piste:</strong></p><ul><li>Multiple terrains (minimum 3-4 pistes)</li><li>Different surfaces if possible (gravel, sand, hard)</li><li>Lighting for evening play</li></ul><p><strong>Indoor Space:</strong></p><ul><li>Room for 20 people in circle (theory sessions)</li><li>Separate from piste</li><li>Whiteboard/projector</li><li>Comfortable seating</li></ul><p><strong>Accommodation:</strong></p><ul><li>On-site or nearby (walking distance)</li><li>Shared rooms encourage bonding</li><li>Quiet space for reflection</li></ul><p><strong>Catering:</strong></p><ul><li>Nutrition-focused meals (see <a href="./food">Food Guide</a>)</li><li>Avoid sugar crashes</li><li>Hydration stations</li></ul></div><h3 id="materials-checklist" tabindex="-1">Materials Checklist <a class="header-anchor" href="#materials-checklist" aria-label="Permalink to &quot;Materials Checklist&quot;">​</a></h3><details class="details custom-block"><summary>Complete Materials List</summary><p><strong>Theory Sessions:</strong></p><ul><li>[ ] Chairs for circle (no tables)</li><li>[ ] Boules and cochonnet for center</li><li>[ ] Flip charts and markers</li><li>[ ] Sticky notes</li><li>[ ] Worksheets (User Manual, Inner Critic, etc.)</li><li>[ ] Paper and pens</li><li>[ ] Projector (for website content)</li></ul><p><strong>Practice Sessions:</strong></p><ul><li>[ ] Measuring tape</li><li>[ ] Cones/markers for drills</li><li>[ ] Video camera/tripod</li><li>[ ] Clipboard and paper (tracking)</li><li>[ ] Whistle</li></ul><p><strong>Competition:</strong></p><ul><li>[ ] Score sheets</li><li>[ ] Tournament bracket</li><li>[ ] Prizes/recognition</li><li>[ ] First aid kit</li></ul><p><strong>Logistics:</strong></p><ul><li>[ ] Name tags</li><li>[ ] Participant list with contacts</li><li>[ ] Emergency contact info</li><li>[ ] Water bottles</li><li>[ ] Sunscreen</li><li>[ ] Tissues (for emotional work!)</li></ul></details><h2 id="weekend-schedule" tabindex="-1">Weekend Schedule <a class="header-anchor" href="#weekend-schedule" aria-label="Permalink to &quot;Weekend Schedule&quot;">​</a></h2><h3 id="friday-evening-3-hours" tabindex="-1">Friday Evening (3 hours) <a class="header-anchor" href="#friday-evening-3-hours" aria-label="Permalink to &quot;Friday Evening (3 hours)&quot;">​</a></h3><p><strong>18:00-18:30 - Arrival &amp; Welcome</strong></p><ul><li>Check-in</li><li>Room assignments</li><li>Overview of weekend</li></ul><p><strong>18:30-19:30 - Dinner</strong></p><ul><li>Nutrition-focused meal</li><li>Informal introductions</li></ul><p><strong>19:30-22:30 - Theory Session: Foundation</strong></p><p>Use the <a href="./workshop">Workshop guide</a> for detailed facilitation:</p><ol><li><strong>Ground Rules (15 min)</strong> - Establish psychological safety</li><li><strong>Check-In Matrix (20 min)</strong> - Assess group energy</li><li><strong>The Iceberg (30 min)</strong> - Explore inner thoughts</li><li><strong>User Manual (45 min)</strong> - Build team understanding</li><li><strong>Fear in a Hat (45 min)</strong> - Break isolation</li><li><strong>Check-Out (15 min)</strong> - Close the loop</li></ol><p><strong>22:30 - Free Time</strong></p><ul><li>Informal socializing</li><li>Rest and reflection</li></ul>',69)),(o(),n(u,null,{default:r(()=>[s(m,{id:"mermaid-1005",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BFriday%20Theory%5D%20--%3E%20B%5BPsychological%20Safety%5D%0A%20%20%20%20B%20--%3E%20C%5BSelf-Awareness%5D%0A%20%20%20%20C%20--%3E%20D%5BTeam%20Understanding%5D%0A%20%20%20%20D%20--%3E%20E%5BReady%20for%20Practice%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23fff4e1%0A%20%20%20%20style%20E%20fill%3A%23e8f5e9%0A"})]),fallback:r(()=>[...d[1]||(d[1]=[l(" Loading... ",-1)])]),_:1})),d[4]||(d[4]=a('<h3 id="saturday-full-day-theory-practice" tabindex="-1">Saturday (Full Day - Theory + Practice) <a class="header-anchor" href="#saturday-full-day-theory-practice" aria-label="Permalink to &quot;Saturday (Full Day - Theory + Practice)&quot;">​</a></h3><p><strong>08:00-09:00 - Breakfast &amp; Mindfulness</strong></p><ul><li>Quiet breakfast</li><li>Optional 15-minute guided meditation</li><li>Set intentions for the day</li></ul><p><strong>09:00-10:30 - Theory Session: Connecting Content to Experience</strong></p><p>Choose 3-4 topics from the Academy website and explore the inner game:</p><p><strong>Example Topics:</strong></p><ol><li><p><strong><a href="./education/nutrition/">Nutrition</a></strong> (20 min)</p><ul><li>&quot;How does your food choice change under pressure?&quot;</li><li>&quot;Do you eat what your body needs or what your anxiety wants?&quot;</li><li>Practice: Plan competition-day nutrition</li></ul></li><li><p><strong><a href="./education/mental-strength/">Mental Strength</a></strong> (25 min)</p><ul><li>&quot;What&#39;s your relationship with failure?&quot;</li><li>&quot;How do you talk to yourself after a miss?&quot;</li><li>Activity: Reframe Inner Critic to Inner Coach</li></ul></li><li><p><strong><a href="./education/mindfulness/">Mindfulness</a></strong> (25 min)</p><ul><li>&quot;Where does your mind go during the pause before throwing?&quot;</li><li>&quot;What pulls you out of the present moment?&quot;</li><li>Practice: 5-minute body scan</li></ul></li><li><p><strong><a href="./education/tactics/">Tactics</a></strong> (20 min)</p><ul><li>&quot;Is your shot choice based on strategy or fear?&quot;</li><li>&quot;When do you play it safe vs. take risks?&quot;</li><li>Discuss: Risk profiles in the group</li></ul></li></ol><p><strong>10:30-10:45 - Break</strong></p><p><strong>10:45-12:30 - On-Piste Integration: Drills with Mental Focus</strong></p><p><strong>Drill 1: Call Your Shot (30 min)</strong></p><p>From the <a href="./workshop">Workshop guide</a> - practice owning intention and doubt:</p><ol><li>Announce the target: &quot;I am shooting the iron&quot;</li><li>State confidence: &quot;I am a 7 out of 10&quot;</li><li>Name the inner thought: &quot;My inner voice is worrying about backspin&quot;</li><li>Execute the shot</li><li>Reflect: &quot;What happened? What did you learn?&quot;</li></ol><p><strong>Drill 2: Cognitive Interference (30 min)</strong></p><p>Test if technique has become automatic:</p><ul><li>Coordinator asks complex questions while player shoots</li><li>&quot;Name 5 capital cities&quot; or &quot;Count backwards from 100 by 7s&quot;</li><li>Success = technique is implicit, not consciously processed</li></ul><p><strong>Drill 3: User Manual Practice (30 min)</strong></p><p>Apply the User Manuals from Friday:</p><ul><li>Play in teams of 3</li><li>After each shot, teammates respond according to User Manual</li><li>&quot;Marc needs silence after a miss&quot; - team honors that</li><li>Debrief: &quot;How did it feel to be understood?&quot;</li></ul><p><strong>12:30-14:00 - Lunch &amp; Rest</strong></p><ul><li>Nutrition-focused meal</li><li>Quiet time for reflection</li><li>Optional: Individual check-ins with coordinator</li></ul><p><strong>14:00-17:00 - Practice Session: Terrain Adaptation</strong></p><p><strong>Goal:</strong> Build adaptability and mental flexibility</p><p><strong>Setup:</strong></p><ul><li>Rotate through 3-4 different terrains/pistes</li><li>45 minutes per terrain</li><li>Focus on mental adaptation, not just technical</li></ul><p><strong>Rotation Structure:</strong></p><table tabindex="0"><thead><tr><th>Terrain</th><th>Mental Focus</th><th>Practice</th></tr></thead><tbody><tr><td><strong>Terrain 1: Soft/Sand</strong></td><td>Acceptance of uncertainty</td><td>&quot;The donnée - accept what is&quot;</td></tr><tr><td><strong>Terrain 2: Hard/Gravel</strong></td><td>Precision under pressure</td><td>&quot;Trust your technique&quot;</td></tr><tr><td><strong>Terrain 3: Uneven</strong></td><td>Emotional regulation</td><td>&quot;Stay calm when it&#39;s unfair&quot;</td></tr><tr><td><strong>Terrain 4: Competition</strong></td><td>Flow state access</td><td>&quot;Find the zone&quot;</td></tr></tbody></table><p><strong>Facilitation:</strong></p><ul><li>Technical coach provides feedback on technique</li><li>MPC asks: &quot;What&#39;s happening in your mind right now?&quot;</li><li>Players journal between rotations</li></ul><p><strong>17:00-18:00 - Break &amp; Reflection</strong></p><ul><li>Individual journaling</li><li>&quot;What did you learn about yourself today?&quot;</li><li>&quot;What&#39;s one thing you&#39;ll do differently tomorrow?&quot;</li></ul><p><strong>18:00-19:00 - Dinner</strong></p><p><strong>19:00-21:00 - Evening Theory: Deep Vulnerability</strong></p><p><strong>Activity 1: Reframing the Inner Critic (45 min)</strong></p><p>See <a href="./workshop">Workshop guide</a> for full protocol:</p><ol><li>Identify the exact Critic phrase</li><li>Reframe as Inner Coach</li><li>Partner practice</li></ol><p><strong>Activity 2: Competition Preparation (45 min)</strong></p><p>Tomorrow is competition day. Prepare mentally:</p><ol><li><p><strong>Visualization (15 min)</strong></p><ul><li>Close eyes</li><li>Imagine perfect shot</li><li>Feel the confidence</li><li>Notice the calm</li></ul></li><li><p><strong>Team Protocols (20 min)</strong></p><ul><li>Create signals for support</li><li>&quot;I need a reset&quot; = touch boules</li><li>&quot;I need encouragement&quot; = fist bump</li><li>&quot;I need space&quot; = step back</li></ul></li><li><p><strong>Set Intentions (10 min)</strong></p><ul><li>&quot;Tomorrow, I will focus on...&quot;</li><li>&quot;My goal is not to win, but to...&quot;</li><li>&quot;I will practice...&quot;</li></ul></li></ol><p><strong>Check-Out (30 min)</strong></p><ul><li>Share one fear about tomorrow</li><li>Share one intention</li><li>Group support</li></ul><p><strong>21:00 - Free Time</strong></p><ul><li>Early to bed (competition tomorrow!)</li><li>Quiet reflection</li></ul><h3 id="sunday-competition-day" tabindex="-1">Sunday (Competition Day) <a class="header-anchor" href="#sunday-competition-day" aria-label="Permalink to &quot;Sunday (Competition Day)&quot;">​</a></h3><p><strong>08:00-09:00 - Breakfast &amp; Mental Preparation</strong></p><ul><li>Light breakfast (see <a href="./education/nutrition/">Nutrition guide</a>)</li><li>15-minute mindfulness practice</li><li>Team huddles</li></ul><p><strong>09:00-09:30 - Competition Briefing</strong></p><p><strong>Format:</strong> Round-robin tournament</p><ul><li>Teams of 3</li><li>Play to 13 points</li><li>Everyone plays everyone</li><li>Focus on PROCESS, not outcome</li></ul><p><strong>The Twist: Mental Performance Scoring</strong></p><div class="tip custom-block"><p class="custom-block-title">Dual Scoring System</p><p><strong>Traditional:</strong> Points won <strong>Mental Performance:</strong> Scored by MPC</p><p>Mental Performance Points (0-5 per game):</p><ul><li>Used User Manual tools</li><li>Supported teammates effectively</li><li>Managed inner critic</li><li>Stayed present (not dwelling on past shots)</li><li>Demonstrated psychological safety</li></ul><p><strong>Winner:</strong> Best combined score (traditional + mental)</p></div><p><strong>09:30-13:00 - Morning Competition</strong></p><ul><li>Round-robin games</li><li>MPC observes and scores</li><li>Technical coach provides brief feedback between games</li><li>Hydration and snack breaks</li></ul><p><strong>13:00-14:00 - Lunch</strong></p><ul><li>Nutrition-focused</li><li>Informal reflection</li><li>Rest</li></ul><p><strong>14:00-17:00 - Afternoon Competition</strong></p><ul><li>Continue round-robin</li><li>Semi-finals and finals</li><li>Increasing pressure</li><li>Apply morning learnings</li></ul><p><strong>17:00-17:30 - Awards &amp; Recognition</strong></p><p><strong>Categories:</strong></p><ul><li>Traditional winner</li><li>Mental performance winner</li><li>Most improved</li><li>Best teammate</li><li>Courage award (most vulnerable)</li></ul><p><strong>17:30-19:00 - Final Reflection Session</strong></p><p><strong>Critical:</strong> This is where learning is cemented.</p><p><strong>Structure:</strong></p><p><strong>1. Individual Reflection (15 min)</strong> Write in journal:</p><ul><li>What did you learn about yourself this weekend?</li><li>What surprised you?</li><li>What will you do differently?</li><li>What are you taking home?</li></ul><p><strong>2. Small Group Sharing (30 min)</strong> Groups of 4-5:</p><ul><li>Share key insights</li><li>What resonated most?</li><li>What was hardest?</li><li>What was most valuable?</li></ul><p><strong>3. Full Group Integration (30 min)</strong> Circle up:</p><ul><li>Each person shares ONE key takeaway</li><li>MPC validates and connects themes</li><li>Discuss: &quot;How will you apply this?&quot;</li></ul><p><strong>4. Commitments (15 min)</strong></p><ul><li>Each person states one commitment</li><li>&quot;In my next competition, I will...&quot;</li><li>Group witnesses and supports</li></ul><p><strong>5. Closing (15 min)</strong></p><ul><li>Thank participants for courage</li><li>Remind of confidentiality</li><li>Exchange contacts</li><li>Plan follow-up (optional online session)</li></ul><p><strong>19:00 - Dinner &amp; Departure</strong></p><h2 id="facilitation-tips" tabindex="-1">Facilitation Tips <a class="header-anchor" href="#facilitation-tips" aria-label="Permalink to &quot;Facilitation Tips&quot;">​</a></h2><h3 id="balancing-theory-and-practice" tabindex="-1">Balancing Theory and Practice <a class="header-anchor" href="#balancing-theory-and-practice" aria-label="Permalink to &quot;Balancing Theory and Practice&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Don&#39;t Overload Theory</p><p><strong>The mistake:</strong> Too much talking, not enough doing</p><p><strong>The balance:</strong></p><ul><li>Theory creates awareness</li><li>Practice builds skill</li><li>Competition tests integration</li><li>Reflection cements learning</li></ul><p><strong>Rule of thumb:</strong> 30% theory, 40% practice, 20% competition, 10% reflection</p></div><h3 id="managing-group-dynamics" tabindex="-1">Managing Group Dynamics <a class="header-anchor" href="#managing-group-dynamics" aria-label="Permalink to &quot;Managing Group Dynamics&quot;">​</a></h3><p><strong>The Competitive Alpha:</strong></p><ul><li>Wants to win at all costs</li><li>Resists vulnerability</li><li><strong>Strategy:</strong> Channel competitiveness into mental performance scoring</li></ul><p><strong>The Quiet Observer:</strong></p><ul><li>Takes it all in, doesn&#39;t share</li><li><strong>Strategy:</strong> Create low-stakes entry points, validate observation as participation</li></ul><p><strong>The Skeptic:</strong></p><ul><li>&quot;This touchy-feely stuff doesn&#39;t work&quot;</li><li><strong>Strategy:</strong> Verbal Aikido - align and pivot (see <a href="./workshop">Workshop guide</a>)</li></ul><p><strong>The Over-Sharer:</strong></p><ul><li>Dominates discussion</li><li><strong>Strategy:</strong> &quot;Thank you, let&#39;s hear from others&quot;</li></ul><h3 id="handling-emotional-moments" tabindex="-1">Handling Emotional Moments <a class="header-anchor" href="#handling-emotional-moments" aria-label="Permalink to &quot;Handling Emotional Moments&quot;">​</a></h3><p><strong>Someone cries during Fear in a Hat:</strong></p><ul><li>✅ Normalize: &quot;Tears are courage, not weakness&quot;</li><li>✅ Offer tissue, don&#39;t rush</li><li>✅ Ask: &quot;What do you need right now?&quot;</li><li>❌ Don&#39;t: &quot;It&#39;s okay, don&#39;t cry&quot;</li></ul><p><strong>Conflict between players:</strong></p><ul><li>✅ Pause and address</li><li>✅ &quot;What&#39;s happening right now?&quot;</li><li>✅ Use as learning moment</li><li>❌ Don&#39;t: Ignore or minimize</li></ul><p><strong>Someone shuts down:</strong></p><ul><li>✅ Check in privately during break</li><li>✅ &quot;I noticed you went quiet. What&#39;s up?&quot;</li><li>✅ Offer options: participate differently, take a break</li><li>❌ Don&#39;t: Call out publicly</li></ul><h2 id="post-camp-follow-up" tabindex="-1">Post-Camp Follow-Up <a class="header-anchor" href="#post-camp-follow-up" aria-label="Permalink to &quot;Post-Camp Follow-Up&quot;">​</a></h2><h3 id="immediate-24-48-hours" tabindex="-1">Immediate (24-48 hours) <a class="header-anchor" href="#immediate-24-48-hours" aria-label="Permalink to &quot;Immediate (24-48 hours)&quot;">​</a></h3><p><strong>Send to all participants:</strong></p><ul><li>Thank you message</li><li>Key takeaways summary</li><li>Photos from weekend</li><li>Contact list (with permission)</li><li>Link to resources on website</li></ul><p><strong>Individual check-ins:</strong></p><ul><li>Text anyone who shared heavily</li><li>&quot;How are you feeling about the weekend?&quot;</li><li>Address any vulnerability hangover</li></ul><h3 id="short-term-2-weeks" tabindex="-1">Short-term (2 weeks) <a class="header-anchor" href="#short-term-2-weeks" aria-label="Permalink to &quot;Short-term (2 weeks)&quot;">​</a></h3><p><strong>Optional online session (60-90 min):</strong></p><ul><li>How have you applied learnings?</li><li>What&#39;s working? What&#39;s challenging?</li><li>Peer support and problem-solving</li><li>Reinforce commitments</li></ul><h3 id="long-term-1-3-months" tabindex="-1">Long-term (1-3 months) <a class="header-anchor" href="#long-term-1-3-months" aria-label="Permalink to &quot;Long-term (1-3 months)&quot;">​</a></h3><p><strong>Survey participants:</strong></p><ul><li>What&#39;s different in your game?</li><li>What tools are you still using?</li><li>What would make the next camp better?</li><li>Would you recommend to others?</li></ul><p><strong>Track impact:</strong></p><ul><li>Competition results</li><li>Self-reported confidence</li><li>Team dynamics</li><li>Continued engagement</li></ul><h2 id="adapting-for-different-group-sizes" tabindex="-1">Adapting for Different Group Sizes <a class="header-anchor" href="#adapting-for-different-group-sizes" aria-label="Permalink to &quot;Adapting for Different Group Sizes&quot;">​</a></h2><h3 id="small-camp-10-12-players" tabindex="-1">Small Camp (10-12 players) <a class="header-anchor" href="#small-camp-10-12-players" aria-label="Permalink to &quot;Small Camp (10-12 players)&quot;">​</a></h3><p><strong>Advantages:</strong></p><ul><li>Deeper sharing</li><li>More individual attention</li><li>Stronger bonds</li></ul><p><strong>Adjustments:</strong></p><ul><li>Single group for all theory</li><li>More time per person in activities</li><li>Intimate competition format</li></ul><h3 id="large-camp-16-20-players" tabindex="-1">Large Camp (16-20 players) <a class="header-anchor" href="#large-camp-16-20-players" aria-label="Permalink to &quot;Large Camp (16-20 players)&quot;">​</a></h3><p><strong>Advantages:</strong></p><ul><li>Diverse perspectives</li><li>More competition variety</li><li>Economies of scale</li></ul><p><strong>Adjustments:</strong></p><ul><li>Split into 2 groups for some theory sessions</li><li>Need 2 MPC/facilitators</li><li>Larger tournament bracket</li><li>More structured rotations</li></ul><h2 id="budget-considerations" tabindex="-1">Budget Considerations <a class="header-anchor" href="#budget-considerations" aria-label="Permalink to &quot;Budget Considerations&quot;">​</a></h2><h3 id="revenue" tabindex="-1">Revenue <a class="header-anchor" href="#revenue" aria-label="Permalink to &quot;Revenue&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Price per Person</th><th>20 People</th><th>10 People</th></tr></thead><tbody><tr><td><strong>Registration</strong></td><td>€150-250</td><td>€3,000-5,000</td><td>€1,500-2,500</td></tr></tbody></table><h3 id="expenses" tabindex="-1">Expenses <a class="header-anchor" href="#expenses" aria-label="Permalink to &quot;Expenses&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Category</th><th>Cost</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Facility rental</strong></td><td>€500-1,000</td><td>Weekend rate</td></tr><tr><td><strong>Accommodation</strong></td><td>€40-60/person/night</td><td>Shared rooms</td></tr><tr><td><strong>Meals</strong></td><td>€30-40/person/day</td><td>6 meals</td></tr><tr><td><strong>Staff</strong></td><td>€500-1,000</td><td>MPC + coaches</td></tr><tr><td><strong>Materials</strong></td><td>€100-200</td><td>Worksheets, supplies</td></tr><tr><td><strong>Prizes</strong></td><td>€100-200</td><td>Recognition items</td></tr></tbody></table><p><strong>Total per person:</strong> €120-180 <strong>Margin:</strong> €30-70/person (or break-even for community building)</p><h2 id="success-metrics" tabindex="-1">Success Metrics <a class="header-anchor" href="#success-metrics" aria-label="Permalink to &quot;Success Metrics&quot;">​</a></h2><h3 id="immediate-indicators" tabindex="-1">Immediate Indicators <a class="header-anchor" href="#immediate-indicators" aria-label="Permalink to &quot;Immediate Indicators&quot;">​</a></h3><ul><li>[ ] Psychological safety score (1-10 average &gt;7)</li><li>[ ] Participation rate (&gt;80% actively sharing)</li><li>[ ] Completion rate (&gt;90% stay full weekend)</li><li>[ ] Satisfaction score (1-10 average &gt;8)</li></ul><h3 id="long-term-indicators" tabindex="-1">Long-term Indicators <a class="header-anchor" href="#long-term-indicators" aria-label="Permalink to &quot;Long-term Indicators&quot;">​</a></h3><ul><li>[ ] Behavior change (using tools in competition)</li><li>[ ] Performance improvement (self-reported)</li><li>[ ] Community building (staying in touch)</li><li>[ ] Referrals (recommending to others)</li></ul><h2 id="common-mistakes-to-avoid" tabindex="-1">Common Mistakes to Avoid <a class="header-anchor" href="#common-mistakes-to-avoid" aria-label="Permalink to &quot;Common Mistakes to Avoid&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Pitfalls</p><p><strong>1. Too much content</strong></p><ul><li>Trying to cover everything</li><li><strong>Fix:</strong> Focus on depth, not breadth</li></ul><p><strong>2. Skipping reflection</strong></p><ul><li>Rushing to next activity</li><li><strong>Fix:</strong> Build in processing time</li></ul><p><strong>3. Ignoring resistance</strong></p><ul><li>Pushing through skepticism</li><li><strong>Fix:</strong> Address it directly with Verbal Aikido</li></ul><p><strong>4. Technical coaching during theory</strong></p><ul><li>Mixing roles</li><li><strong>Fix:</strong> Clear boundaries between MPC and technical coach</li></ul><p><strong>5. No follow-up</strong></p><ul><li>Weekend ends, learning stops</li><li><strong>Fix:</strong> Plan post-camp touchpoints</li></ul></div><h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h2><h3 id="from-this-site" tabindex="-1">From This Site <a class="header-anchor" href="#from-this-site" aria-label="Permalink to &quot;From This Site&quot;">​</a></h3><ul><li><a href="./workshop">Workshop Guide</a> - Detailed facilitation protocols</li><li><a href="./training-session">Training Session Guide</a> - For ongoing practice</li><li><a href="./education/nutrition/">Nutrition</a> - Competition-day protocols</li><li><a href="./education/mental-strength/">Mental Strength</a> - Inner game concepts</li><li><a href="./education/mindfulness/">Mindfulness</a> - Presence techniques</li><li><a href="./education/tactics/">Tactics</a> - Strategic thinking</li></ul><h3 id="recommended-reading" tabindex="-1">Recommended Reading <a class="header-anchor" href="#recommended-reading" aria-label="Permalink to &quot;Recommended Reading&quot;">​</a></h3><ul><li><em>The Inner Game of Tennis</em> by Timothy Gallwey</li><li><em>Mindset</em> by Carol Dweck</li><li><em>The Fearless Organization</em> by Amy Edmondson</li></ul>',135))])}]]);export{d as __pageData,c as default};
